INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10780, 'Beacon Bay Marina (part of Maple Leaf Marina Group - 14)', 'Jerry Haggerty', 'jhaggery@beaconbaymarina.com', '7057945173 (cell)', 'Dropped by as i drove by March.6.2026', 'new', 4, 'Ian Kerr is Jerry’s service manager. Jerry is GM. He mentioned they are part of the Mapleleaf Marina‘s group. He mentioned there are 14 marinas. They really love the tech. Gerry even mentioned that this is definitely the future of where things are gonna go, etc. I think that we likely could get some sort of pilot test we just need units and we shouldn’t put our worst foot forward with two point sixes anymore, especially for Marina groups.
