INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10140, 'Port Credit Harbour Marina', 'Wayne Petryk', '', '905-274-1595', 'marina_directory', 'qualified', 4, 'We are located at the mouth of the Credit River in the charming village of Port Credit, Ontario which is conveniently located between Toronto & Oakville. Port Credit Harbor Marina is within walking distance of shops, restaurants, drug stores, banks, food stores, the Go station and the waterfront trail.
INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10781, 'Hindson Marina (they own 7 and manage 1)', 'Tom Grabinsky (GM)', '', '', '', 'new', NULL, 'Had a good meeting with him was for about an hour and a half. He sent me a text with some questions that I need to answer and send back to him therefore, his guy that wasn’t able to be here. They wanna know pricing and he’s like convinced that he wants to try it out at 3 to 4 of his Marina’s maybe a certain amount six or so at each Marina. I explained to him that it would need to be the 3.0 units which still require safety certification and guided him to the beginning of Q3. They have some 50 amp but mostly 30 amp. He wants to know how much for the software how much for the hardware I guided him a bit on it to about $3000 for next two also guided him that the software was also very appealing for any purchase orders that come in in 2026 from them and is more competitive even than Aqua and that we give additional perks to Marina‘s doing purchase orders in 2026. I could tell that he kind of just wants now to get to the brass tax of it all they really like the system they just wanna figure out. Will it fit the budget and they wanna at least try it out and then see what a full quote would look like if they were to consider changing all the marines over which total seven marinas that they own and one extra Marina that they manage. He and two others essentially own all of the marinas.', NULL, NULL, NULL, '2026-03-06 21:28:05.197813', '2026-03-06 21:28:05.197813', NULL, 'Ontario', 'Penetanguishene', NULL, NULL, NULL, NULL, 'CA', NULL, 'USD', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10024, 'Gordon Yacht Harbour Marina', 'Angel Allegri', NULL, '705-738-2381', 'marina_directory', 'new', NULL, 'For over 100 years **Gordon Yacht Harbour Marina** has been located in the heart of the Village of **Bobcaygeon**, below Lock 32 on **Pigeon Lake** on the Trent-Severn Waterway. Approximately a two hour drive north-east from **Toronto, Ontario,Canada.**
INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10187, 'Sarnia Bay Marina', 'Dave Brown', NULL, '519-332-0533', 'marina_directory', 'new', NULL, 'With over 30 beautifully landscaped acres and spectacular views of the Blue Water Bridges, Sarnia Bay Marina offers boaters a full service "lifestyle" marina that includes over 350 boat slips for both seasonal members and tourist (transient) boaters. The up-to-date facility and staff offer an endless array of amenities and services to all guests.
INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (9973, 'Bridgeview Marina', 'Dave Brown', NULL, '519-337-3888', 'marina_directory', 'new', NULL, 'One of the largest full serviced Marinas in the Great Lakes, Bridgeview Yachting Centre is located in Point Edward (Sarnia), Ontario, directly across from Port Huron, Michigan at the mouth of Lake Huron. Bridgeview has over 35 beautifully landscaped acres of land, showcasing all of the services and amenities needed for a boater to sit back and enjoy your summer home away from home. Bridgeview has water depth from 7 ft to 15 ft.
INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10164, 'Puce River Harbour Marina', 'Robert Troup', NULL, '519-979-8764', 'marina_directory', 'new', NULL, 'Puce River Harbour Marina, just minutes from Tecumseh, is a private facility offering a variety of services & amenities to meet your boating needs. The marina features a launching ramp, transient overnight dockage space, 65 seasonal wells & 16 jet ski docks. The Sandbar Waterfront Grill is a 300 seat restaurant onsite that is open year round & boasts delicious menu choices & outstanding service not to mention the largest outdoor patio on lake St. Clair. A sheltered harbour, fuel docks with 91 oc
