INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10058, 'Kagawong East Municipal Marina-Aus Hunt Marina', 'Jorja Croft', NULL, '705-282-2611', 'marina_directory', 'new', NULL, 'The Billings municipal marina is your destination for experiencing the unique hamlet of Kagawong. Visit the Old Mill Heritage Centre, which is right on the waterfront. Take one of several trails that lead you to Bridal Veil falls, one of Manitoulin''s premier attractions. 15 minutes of leisurely walking will take you from the marina to the falls. Visit one or all of the community''s unique shops. Kagawong is a quieter, more laid-back marina experience than Little Current and Gore Bay, and is the c
INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10045, 'Hilton Beach Marina', 'Marina Manager', NULL, '705-246-2291', 'marina_directory', 'new', NULL, 'The **[Hilton Beach Marina](http://new.hiltonbeach.com/our-community/hilton-beach-marina/)** is a full-service facility, featuring over 160 slips with at least 30 available to transient boaters. An 8 foot minimum depth is maintained at all docks, and yachts up to 75 feet long can be easily accommodated. Thirty amp and fifty amp electrical service and potable water hookups are available at every slip.
INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10200, 'Spanish Municipal Marina', 'Pam Lortie', NULL, '705-844-1077', 'marina_directory', 'new', NULL, 'The Town of Spanish is located on the TransCanada, between Sudbury and Sault Ste. Marie and is also situated on beautiful Lake Huron, in the midst of the well-known Whalesback and North Channel. Its proximity to the Benjamins and surrounding islands offers popular anchoring spots and protection from prevailing winds. This area is reputed to be among one of the best sailing areas in the world. Spanish provides a unique and enviable quality of life offering many opportunities for residents, busine
INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10176, 'Roberta Bondar Transient Marina', 'Rick Borean', NULL, '705-759-5310', 'marina_directory', 'new', NULL, 'As part of Roberta Bondar Park at 65 Foster Drive, this transient boater facility offers 50 slips and 270-feet of protected dock-face as well as over 400 feet of dock-face outside the marina basin. Docks are serviced with 30 amp GFI protected shore power and potable water with the exception of the 400 feet outside dock-face.
