INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10817, 'Cliff Richardson Boats Ltd.', 'Brian Laporte', NULL, '519-538-1940', 'boating_ontario', 'new', NULL, 'Cliff Richardson Boats Ltd. is a full service Marina located at [Meaford](http://www.meaford.com/town/), Ontario, on Georgian Bay. Their staff has the training and experience to make sure you have a pleasant and trouble-free season on the bay, and confidence that your boat is carefully prepared and stored during the off season, and ready to go again in the spring. Please look over our website and if you have any questions, please call, e-mail, or drop in to see us.
