INSERT INTO public.leads (id, company, contact_name, contact_email, contact_phone, source, status, owner_user_id, notes, tags, next_step, due_date, created_at, updated_at, marina_id, state, city, slips, segment, street_address, zip_code, country, deal_amount, deal_currency, deal_probability, deal_value_hardware, deal_value_software, deal_value_services, primary_value_driver, estimated_pedestal_count, estimated_slips_impacted, est_close_date, competitors, roi_story, closed_lost_reason, closed_won_notes) VALUES (10862, 'Northern Harbour', 'Gary Hall', NULL, '807-548-5719', 'boating_ontario', 'new', NULL, 'Located East of Kenora along the North Shore of Pine Portage Bay, Northern Harbour has become one of central Canada’s largest marinas. Northern Harbour was established in 1976, by Ed Lugossy and the first two docks were constructed by 1977. My wife, Barb, and I purchased Northern Harbour in 1980 with two docks in place. The family-run business has grown to provide seasonal docking and great services to over 200 boats, many valued friends and great customers.
